import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int n = Integer.parseInt(br.readLine());
        double[][] p = new double[n][n];

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                int val = Integer.parseInt(st.nextToken());
                p[i][j] = val / 100.0;
            }
        }

        long[] no_mask = new long[n];
        for (int i = 0; i < n; ++i) {
            long mask = 0;
            for (int j = 0; j < n; ++j) {
                if (j != i) {
                    mask |= (1L << j);
                }
            }
            no_mask[i] = mask;
        }

        Map<Long, Double> states = new HashMap<>();
        states.put(1L, 1.0);

        for (int i = 0; i < n; ++i) {
            Map<Long, Double> next_states = new HashMap<>();
            for (Map.Entry<Long, Double> s : states.entrySet()) {
                long s_mask = s.getKey();
                double s_prob = s.getValue();

                for (int j = 0; j < (1 << n); ++j) {
                    double prob = 1.0;
                    long res = 0L;
                    for (int k = 0; k < n; ++k) {
                        if (((j >> k) & 1) == 1) {
                            prob *= p[i][k];
                            long shifted = (s_mask & no_mask[k]) << (1 << k);
                            res |= shifted;
                        } else {
                            prob *= (1 - p[i][k]);
                        }
                    }
                    next_states.put(res, next_states.getOrDefault(res, 0.0) + s_prob * prob);
                }
            }
            states = next_states;
        }

        double result = states.getOrDefault((1L << n) - 1L, 0.0);
        System.out.printf("%.9f\n", result);
    }
}
